ClassExpression.Expression:
declare query_parameters(startTime:datetime, endTime:datetime);
// Entrepot entity materialization from fn_SurveillanceEntrepots: one row per entrepôt and function execution
let Entrepot =
    ['fn_SurveillanceEntrepots'];
Entrepot | where ['Timestamp'] between (startTime .. endTime)
| project
    Id = ['CodeEntrepot'],
    Timestamp = ['Timestamp'],
    EntrepotMuet = ['EntrepotMuet'],
    EntrepotNom = ['Entrepot'],
    DernierEvenement = ['DernierEvenement'],
    MinutesSansEvenement = ['MinutesSansEvenement']
